#include "../tools/render_host/d3d9_shader_tokens.h"

#include <algorithm>
#include <array>
#include <cstdio>
#include <cstdlib>
#include <limits>
#include <vector>

using namespace warvk::host::d3d9tokens;
using Words = std::vector<uint32_t>;
static unsigned checks = 0;
static void Check(bool condition, unsigned line) {
  ++checks;
  if (!condition) {
    std::fprintf(stderr, "d3d9 shader token check failed line=%u\n", line);
    std::exit(1);
  }
}
#define CHECK(x) Check(bool(x), __LINE__)

static Words Vertex() {
  // Literal SM3 assembly: position/UV/color passthrough, not generated by Scan.
  return {
    0xfffe0300u,
    0x0200001fu, 0x80000000u, 0x900f0000u, // dcl_position v0
    0x0200001fu, 0x80000005u, 0x90030001u, // dcl_texcoord v1.xy
    0x0200001fu, 0x8000000au, 0x900f0002u, // dcl_color v2
    0x0200001fu, 0x80000000u, 0xe00f0000u, // dcl_position o0
    0x0200001fu, 0x80000005u, 0xe0030001u, // dcl_texcoord o1.xy
    0x0200001fu, 0x8000000au, 0xe00f0002u, // dcl_color o2
    0x02000001u, 0xe00f0000u, 0x90e40000u, // mov o0,v0
    0x02000001u, 0xe0030001u, 0x90e40001u, // mov o1.xy,v1
    0x02000001u, 0xe00f0002u, 0x90e40002u, // mov o2,v2
    0x0000ffffu,
  };
}
static Words Pixel() {
  return {
    0xffff0300u,
    0x0200001fu, 0x80000005u, 0x90030000u, // dcl_texcoord v0.xy
    0x0200001fu, 0x8000000au, 0x900f0001u, // dcl_color v1
    0x0200001fu, 0x90000000u, 0xa00f0800u, // dcl_2d s0
    0x03000042u, 0x800f0000u, 0x90e40000u, 0xa0e40800u, // texld r0,v0,s0
    0x03000005u, 0x800f0800u, 0x80e40000u, 0x90e40001u, // mul oC0,r0,v1
    0x0000ffffu,
  };
}
static Words ConstantPixel() {
  return {PixelVersion, 0x02000001u, 0x800f0800u, 0xa0e40000u, EndToken};
}

// Independent access-pattern model of the CURRENT DXSO decoder, not a second
// validator: DCL always reads two words; DEF always reads its destination then
// min(length-1,4); generic relative operands read an extra word. This checks the
// scanner's framing invariant only, not real DXSO compilation or GPU output.
static bool CurrentDecoderReadsStayInside(const Words& words) {
  size_t pos = 1;
  bool inside = true;
  auto read = [&]() {
    if (pos >= words.size()) { inside = false; return uint32_t(0); }
    return words[pos++];
  };
  while (inside && pos < words.size()) {
    const uint32_t token = read(), op = token & 0xffffu;
    const uint32_t length = (token >> 24) & 15u;
    if (op == 0xffffu) return pos == words.size();
    if (op == 0xfffeu) {
      const size_t skip = (token >> 16) & 0x7fffu;
      if (skip > words.size() - pos) return false;
      pos += skip;
    } else if (op == 31) {
      (void)read();
      if (read() & 0x2000u) (void)read();
    } else if (op == 81 || op == 48 || op == 47) {
      if (read() & 0x2000u) (void)read();
      for (uint32_t i = 0; i < std::min(length - 1, 4u); ++i) (void)read();
    } else {
      for (uint32_t i = 0; i < length; ++i) {
        const uint32_t operand = read();
        if (operand & 0x2000u) { (void)read(); ++i; }
      }
    }
  }
  return false;
}

static void Accepted(const Words& words, Stage stage) {
  const auto result = Scan(words.data(), words.size());
  CHECK(result.accepted()); CHECK(result.error == Error::None);
  CHECK(result.stage == stage && result.bytes == words.size() * 4);
  CHECK(CurrentDecoderReadsStayInside(words));
}
static void Refused(const Words& words, Error expected) {
  const auto result = Scan(words.data(), words.size());
  CHECK(!result.accepted()); CHECK(result.error == expected);
  CHECK(result.stage == Stage::None && result.bytes == 0);
}
static void MutationRefused(const Words& base, size_t at, uint32_t value, Error error) {
  Words words = base; words.at(at) = value; Refused(words, error);
}

static void ValidProfile() {
  Accepted(Vertex(), Stage::Vertex); Accepted(Pixel(), Stage::Pixel);
  Accepted(ConstantPixel(), Stage::Pixel);
  for (uint32_t op : {2u, 3u, 5u, 8u, 9u}) {
    Accepted({PixelVersion, 0x03000000u | op, 0x800f0800u,
              0xa0e40000u, 0xa0e40001u, EndToken}, Stage::Pixel);
  }
  Accepted({PixelVersion, 0x04000004u, 0x800f0800u, 0xa0e40000u,
            0xa0e40001u, 0xa0e40002u, EndToken}, Stage::Pixel);
  Words def = ConstantPixel();
  // All immediate bit patterns are data, even END/relative/COMMENT-looking words.
  def.insert(def.begin() + 1, {0x05000051u, 0xa00f0000u,
                             0x0000ffffu, 0xffffffffu, 0x00002000u, 0x7ffffffeu});
  Accepted(def, Stage::Pixel);
  auto translated = Vertex();
  translated[19] = 0x03000002u;
  translated.insert(translated.begin() + 22, 0xa0e40000u); // add o0,v0,c0
  Accepted(translated, Stage::Vertex);
  for (uint32_t mod : {0u, 1u, 11u, 12u}) {
    auto words = ConstantPixel(); words[3] |= mod << 24;
    Accepted(words, Stage::Pixel);
  }
  for (uint32_t modifiers : {0x00100000u, 0x00200000u, 0x00300000u}) {
    auto words = ConstantPixel(); words[2] |= modifiers;
    Accepted(words, Stage::Pixel);
  }
  auto centroid = Pixel(); centroid[3] |= 0x00400000u;
  Accepted(centroid, Stage::Pixel);
  auto comments = Pixel();
  comments.insert(comments.begin() + 1, {0x0003fffeu, EndToken, 0xffffffffu, 0u, 0x0000fffeu});
  Accepted(comments, Stage::Pixel);
  auto nops = ConstantPixel(); nops.insert(nops.begin() + 1, 3, 0u);
  Accepted(nops, Stage::Pixel);
}

static void FramingAndFlags() {
  const auto vertex = Vertex(); const auto pixel = Pixel();
  for (const auto& words : {vertex, pixel}) {
    for (size_t count = 0; count < words.size(); ++count) {
      auto result = Scan(words.data(), count);
      CHECK(!result.accepted() && result.stage == Stage::None && result.bytes == 0);
    }
  }
  CHECK(Scan(nullptr, 0).error == Error::NullInput);
  CHECK(Scan(nullptr, MaxWords).error == Error::NullInput);
  CHECK(Scan(vertex.data(), MaxWords + 1).error == Error::Size);
  CHECK(Scan(vertex.data(), std::numeric_limits<size_t>::max()).error == Error::Size);
  for (uint32_t version : {0u, 0xfffe0200u, 0xffff0104u, 0xfffe0301u, 0xffff0400u, 0xffffff00u})
    MutationRefused(vertex, 0, version, Error::Version);
  auto words = vertex; words.push_back(EndToken); Refused(words, Error::End);
  MutationRefused(vertex, 1, EndToken, Error::End);
  MutationRefused(vertex, vertex.size() - 1, EndToken | 0x01000000u, Error::End);
  words = vertex; words.pop_back(); Refused(words, Error::End);
  for (uint32_t flag : {0x00010000u, 0x10000000u, 0x20000000u, 0x40000000u, 0x80000000u})
    MutationRefused(vertex, 19, vertex[19] | flag, Error::InstructionFlags);
  for (uint32_t length = 0; length < 16; ++length) {
    if (length != 2) MutationRefused(vertex, 1, (length << 24) | 31u, Error::Length);
    if (length != 2) MutationRefused(vertex, 19, (length << 24) | 1u, Error::Length);
    if (length != 3) MutationRefused(pixel, 10, (length << 24) | 66u, Error::Length);
  }
  for (uint32_t op : {6u, 20u, 25u, 27u, 40u, 41u, 47u, 48u, 93u, 0x1234u, 0xfffdu})
    MutationRefused(vertex, 19, 0x02000000u | op, Error::Opcode);
  words = pixel; words.insert(words.begin() + 1, 0x7ffffffeu); Refused(words, Error::Length);
  words = pixel; words.insert(words.begin() + 1, 0x8000fffeu); Refused(words, Error::InstructionFlags);
  // A comment cannot supply a missing END: its embedded terminator is data.
  words = pixel; words.back() = 0x0001fffeu; words.push_back(EndToken); Refused(words, Error::End);
  for (uint32_t length = 0; length < 16; ++length) {
    if (length == 5) continue;
    words = {PixelVersion, (length << 24) | 81u, 0xa00f0000u,
             0, 0, 0, 0, 0x02000001u, 0x800f0800u, 0xa0e40000u, EndToken};
    Refused(words, Error::Length);
  }
}

static void OperandAndDeclarationBoundaries() {
  const auto vertex = Vertex(), pixel = Pixel(), constant = ConstantPixel();
  for (size_t at : {size_t(3), size_t(12), size_t(20), size_t(21)})
    MutationRefused(vertex, at, vertex[at] | 0x2000u, Error::Operand);
  for (uint32_t invalid : {0x20e40000u, 0xa0e42000u, 0xa0e44000u, 0xa0e48000u, 0xa2e40000u})
    MutationRefused(constant, 3, invalid, Error::Operand);
  for (uint32_t invalid : {0x000f0800u, 0x80000800u, 0x810f0800u, 0x804f0800u})
    MutationRefused(constant, 2, invalid, Error::Operand);
  MutationRefused(constant, 3, 0xa0e40000u | 224u, Error::Register);
  MutationRefused(constant, 3, 0x80e40000u | 32u, Error::Register);
  MutationRefused(constant, 2, 0x800f0801u, Error::Register); // MRT1
  MutationRefused(constant, 2, 0xa00f0000u, Error::Register); // write a constant via MOV
  MutationRefused(vertex, 3, 0x900f0010u, Error::Register); // v16
  MutationRefused(vertex, 12, 0xe00f000cu, Error::Register); // o12
  MutationRefused(pixel, 3, 0x9003000au, Error::Register); // PS v10
  MutationRefused(pixel, 9, 0xa00f0808u, Error::Register); // sampler8 outside profile
  MutationRefused(pixel, 8, 0x98000000u, Error::Declaration); // cube sampler
  MutationRefused(pixel, 13, 0xa0e40801u, Error::Declaration); // undeclared sampler1
  MutationRefused(pixel, 13, 0xa0e40808u, Error::Operand); // TEX sampler8
  for(uint32_t i=0;i<8;++i) {
    auto multi=pixel;multi[9]=0xa00f0800u|i;multi[13]=0xa0e40800u|i;
    Accepted(multi,Stage::Pixel);
  }
  MutationRefused(pixel, 13, 0xa1e40800u, Error::Operand); // modified sampler
  MutationRefused(pixel, 10, 0x03010042u, Error::InstructionFlags); // project TEX
  MutationRefused(vertex, 2, 0u, Error::Declaration); // missing semantic marker
  MutationRefused(vertex, 2, 0x80000009u, Error::Declaration); // POSITIONT out of profile
  MutationRefused(vertex, 5, 0x80080005u, Error::Declaration); // texcoord8
  MutationRefused(vertex, 8, 0x8002000au, Error::Declaration); // color2
  MutationRefused(vertex, 6, 0x90030000u, Error::Declaration); // duplicate v0
  MutationRefused(vertex, 5, 0x80000000u, Error::Declaration); // duplicate POSITION input
  MutationRefused(vertex, 21, 0x90e40003u, Error::Declaration); // undeclared v3
  MutationRefused(vertex, 20, 0xe00f0003u, Error::Declaration); // undeclared o3
  auto words = pixel; words.erase(words.begin() + 7, words.begin() + 10);
  Refused(words, Error::Declaration); // TEX without sampler declaration
  words = vertex; words.insert(words.end() - 1, {0x0200001fu, 0x80010005u, 0x90030003u});
  Refused(words, Error::Declaration); // declaration after execution
  words = {VertexVersion, 0x0200001fu, 0x80000000u, 0xe00f0000u,
           0x03000042u, 0x800f0000u, 0xa0e40000u, 0xa0e40800u, EndToken};
  Refused(words, Error::Register); // vertex texture instruction
  Refused({VertexVersion, EndToken}, Error::Declaration);
  Refused({PixelVersion, 0, EndToken}, Error::Declaration);
  MutationRefused(vertex, 20, 0xe0070000u, Error::Declaration); // no POSITION.w write
  MutationRefused(constant, 2, 0x80070800u, Error::Declaration); // no color alpha write
  words = {PixelVersion, 0x05000051u, 0xa00f0000u, 0, 0, 0, 0,
           0x05000051u, 0xa00f0000u, 0, 0, 0, 0,
           0x02000001u, 0x800f0800u, 0xa0e40000u, EndToken};
  Refused(words, Error::Declaration); // duplicate definition
  words.erase(words.begin() + 1, words.begin() + 7);
  words[2] = 0xa00f00e0u; Refused(words, Error::Register); // DEF c224 in PS
}

static void ConstantRegisterBoundaries() {
  static_assert(FloatRegisters == 32);
  for (Stage stage : {Stage::Vertex, Stage::Pixel}) {
    // Independently encoded boundary operands: c31 is supported, c32 is not.
    Words words = stage == Stage::Vertex
        ? Words{VertexVersion, 0x0200001fu, 0x80000000u, 0xe00f0000u,
                0x02000001u, 0xe00f0000u, 0xa0e4001fu, EndToken}
        : Words{PixelVersion, 0x02000001u, 0x800f0800u, 0xa0e4001fu, EndToken};
    Accepted(words, stage);
    MutationRefused(words, words.size() - 2, 0xa0e40020u, Error::Register);
    words.insert(words.begin() + 1, {0x05000051u, 0xa00f001fu, 0, 0, 0, 0});
    Accepted(words, stage);
    MutationRefused(words, 2, 0xa00f0020u, Error::Register);
  }
}

static void CapsAndAcceptedMutationSafety() {
  auto words = ConstantPixel();
  const size_t commentWords = MaxWords - words.size() - 1;
  words.insert(words.begin() + 1, commentWords + 1, 0xffffffffu);
  words[1] = uint32_t(commentWords << 16) | 0xfffeu;
  CHECK(words.size() == MaxWords); Accepted(words, Stage::Pixel);
  words.insert(words.begin() + 2, 0u); Refused(words, Error::Size);
  for (const auto& valid : {Vertex(), Pixel(), ConstantPixel()}) {
    for (size_t i = 0; i < valid.size(); ++i) {
      for (uint32_t bit = 0; bit < 32; ++bit) {
        auto changed = valid; changed[i] ^= 1u << bit;
        const auto result = Scan(changed.data(), changed.size());
        if (result.accepted()) {
          CHECK(result.bytes == changed.size() * 4);
          CHECK(CurrentDecoderReadsStayInside(changed));
        } else CHECK(result.bytes == 0 && result.stage == Stage::None);
      }
    }
  }
  // Fixed-seed malformed corpus; no unbounded native-pointer reads are used.
  uint32_t random = 0x36f21a09u;
  for (uint32_t sample = 0; sample < 4096; ++sample) {
    std::array<uint32_t, 64> input{};
    for (auto& word : input) {
      random ^= random << 13; random ^= random >> 17; random ^= random << 5;
      word = random;
    }
    input[0] = sample & 1 ? VertexVersion : PixelVersion;
    const size_t count = 2 + sample % 63;
    input[count - 1] = EndToken;
    const auto result = Scan(input.data(), count);
    if (result.accepted()) {
      Words accepted(input.begin(), input.begin() + count);
      CHECK(CurrentDecoderReadsStayInside(accepted));
    } else CHECK(result.stage == Stage::None && result.bytes == 0);
  }
}

int main() {
  static_assert(noexcept(Scan(nullptr, 0)));
  ValidProfile(); FramingAndFlags(); OperandAndDeclarationBoundaries();
  ConstantRegisterBoundaries();
  CapsAndAcceptedMutationSafety();
  std::printf("d3d9 shader tokens checks=%u failures=0 bits=%zu maxWords=%zu "
              "floatRegisters=%u restrictedSm3=1 boundedFraming=1 cpuOnly=1 "
              "dxsoCompileTested=0 gpuTested=0\n",
              checks, sizeof(void*) * 8, MaxWords, FloatRegisters);
}
